u751f\u6210\u7684\u4e2d\u95f4\u5e27\u5728\u9010\u5e27\u626d\u8f6c\u89d2\u77ac\u65f6\u8bef\u5dee\u4e0a\u663e\u8457\u4f18\u4e8e\u7ebf\u6027\u63d2\u503c\u3001\u968f\u673a\u57fa\u7ebf\u4e0e\u51bb\u7ed3\u63a7\u5236,\u5e76\u63a5\u8fd1\u91d1\u6807\u51c6\u3002\n**H2**:MDGEN \u6062\u590d\u7684\u626d\u8f6c\u89d2 ACF \u7684\u8870\u51cf\u65f6\u95f4\u4e0e\u632f\u8361\u5468\u671f\u4e0e\u91d1\u6807\u51c6\u4e00\u81f4(\u5728\u9884\u5b9a\u4e49\u5bb9\u5dee\u5185)\u3002\n**H3**(\u7ed3\u6784\u4fdd\u771f):\u751f\u6210\u5e27\u7684\u9759\u6001\u7ed3\u6784\u91cf(RDF\u3001\u952e\u957f/\u952e\u89d2\u5206\u5e03)\u4e0e\u91d1\u6807\u51c6\u4e00\u81f4\u3002\n**H4**(\u654f\u611f\u6027):\u7ed3\u8bba\u5728\u591a\u4e2a\u5b50\u91c7\u6837\u56e0\u5b50 k \u4e0b\u7a33\u5065;\u968f k \u589e\u5927(\u4e22\u5931\u66f4\u5feb\u65f6\u95f4\u5c3a\u5ea6),\u5404\u65b9\u6cd5\u6027\u80fd\u5355\u8c03\u9000\u5316,MDGEN \u7684\u76f8\u5bf9\u4f18\u52bf\u533a\u95f4\u53ef\u88ab\u523b\u753b\u3002\n\n**\u524d\u63d0\u5047\u8bbe(\u660e\u786e\u6807\u6ce8)**:\u5b58\u5728\u4e00\u4e2a\"\u7ed9\u5b9a\u7684 MDGEN \u7c7b\u751f\u6210\u6a21\u578b\"\u2014\u2014\u8f93\u5165\u538b\u7f29\u65f6\u95f4\u6b65\u7c97\u5e27\u5e8f\u5217,\u8f93\u51fa\u4e24\u5e27\u4e4b\u95f4\u7684\u4e2d\u95f4\u5e27\u3002**\u672c\u8bbe\u8ba1\u4e0d\u8981\u6c42\u590d\u73b0\u5176\u5177\u4f53\u67b6\u6784**,\u5c06\u5176\u89c6\u4e3a\u5f85\u8bc4\u4f30\u7684\u9ed1\u7bb1\u751f\u6210\u5668(\u5177\u4f53\u5b9e\u73b0\u53ef\u7528\u4efb\u4e00\u6ee1\u8db3\u8be5\u63a5\u53e3\u7684\u751f\u6210\u5f0f\u6a21\u578b,\u5982\u6761\u4ef6\u751f\u6210\u7f51\u7edc/\u6269\u6563\u6a21\u578b;\u6b64\u9009\u62e9\u672c\u8eab\u662f\u5047\u8bbe)\u3002\n\n---\n\n## 2. \u5206\u5b50\u4f53\u7cfb\u4e0e\u6570\u636e\u751f\u6210\u6d41\u7a0b\n\n### 2.1 \u4f53\u7cfb\u9009\u62e9(\u5047\u8bbe)\n- **\u4e3b\u4f53\u7cfb**:\u6c14\u76f8\u6216\u9690\u5f0f\u6eb6\u5242**\u4e19\u6c28\u9178\u4e8c\u80bd(Ace\u2013Ala\u2013NMe)**\u2014\u2014\u626d\u8f6c\u89d2 \u03c6/\u03c8 \u632f\u8361\u660e\u786e\u3001ps \u7ea7\u65f6\u95f4\u5c3a\u5ea6\u6587\u732e\u8bb0\u8f7d\u5145\u5206\u3001\u7b97\u529b\u9700\u6c42\u6781\u5c0f\u3002\n- **\u6b21\u4f53\u7cfb(\u7a33\u5065\u6027)**:\u4e00\u4e2a\u7a0d\u5927\u7684\u4f53\u7cfb(\u5982 CLN025/Chignolin,10 \u80bd,\u542b\u66f4\u591a \u03c7 \u89d2),\u4ec5\u7528\u4e8e\u68c0\u9a8c\u7ed3\u8bba\u7684\u8fc1\u79fb\u6027;\u82e5\u7b97\u529b\u4e0d\u8db3\u53ef\u964d\u7ea7\u4e3a\u53ef\u9009\u3002\n- **\u6807\u6ce8**:\u539f\u8bba\u6587\u82e5\u6709\u6307\u5b9a\u6570\u636e\u96c6,\u4ee5\u5176\u4e3a\u51c6;\u5426\u5219\u4e0a\u8ff0\u9009\u62e9\u4e3a**\u5408\u7406\u66ff\u4ee3(\u5047\u8bbe)**\u3002\n\n### 2.2 \u91d1\u6807\u51c6\u8f68\u8ff9\u751f\u6210\n- \u529b\u573a:amber99sb-ildn \u6216 ff14SB(\u5047\u8bbe,\u4efb\u4e00\u6807\u51c6\u529b\u573a\u5373\u53ef);\n- \u5f15\u64ce:OpenMM(CPU \u591a\u7ebf\u7a0b,\u73af\u5883\u6709 224 \u6838,\u53ef\u884c);\n- \u79ef\u5206\u6b65\u957f \u0394t\u2080 = 1 fs(HMR \u540e\u53ef\u7528 2\u20134 fs,\u5b58\u5e27\u95f4\u9694\u53d6 1 fs);\n- \u6bcf\u6761\u8f68\u8ff9 **100 ns**,\u5b58\u5e27\u95f4\u9694 **1 fs** \u2192 \u6bcf\u6761\u8f68\u8ff9 10\u2075 \u5e27;\n- **\u72ec\u7acb\u8f68\u8ff9\u6570:N = 5 \u6761**(\u4e0d\u540c\u521d\u59cb\u901f\u5ea6\u79cd\u5b50)\u2192 \u5171 500 ns \u91d1\u6807\u51c6\u6570\u636e;\n- \u524d 10% \u7528\u4f5c\u5e73\u8861\u5f03\u7f6e;\u8bad\u7ec3/\u8bc4\u4f30\u5212\u5206\u6309\u8f68\u8ff9\u5212\u5206(\u89c1 \u00a76)\u3002\n\n### 2.3 \u5b50\u91c7\u6837(\u538b\u7f29\u65f6\u95f4\u6b65,MDCT)\u6784\u9020\n\u5bf9\u6bcf\u6761\u91d1\u6807\u51c6\u8f68\u8ff9,\u673a\u68b0\u5730\u6bcf k \u5e27\u53d6 1 \u5e27,\u6784\u9020\u4e09\u6761\u538b\u7f29\u8f68\u8ff9:\n- **k = 10**(\u5b58\u5e27\u95f4\u9694 10 fs)\u3001**k = 50**(50 fs)\u3001**k = 100**(100 fs)\u3002\n- \u4f9d\u636e(\u5047\u8bbe):\u4e19\u6c28\u9178\u4e8c\u80bd \u03c6/\u03c8 \u5f1b\u8c6b\u4e0e\u632f\u8361\u65f6\u95f4\u5c3a\u5ea6\u5728 ps \u91cf\u7ea7,\u8be5\u4e09\u6863\u8986\u76d6\u4ece\"\u8f7b\u5ea6\u4e22\u5931\"\u5230\"\u4e25\u91cd\u4e22\u5931\"\u7684\u8303\u56f4;**\u82e5\u7814\u7a76\u8005\u63d0\u4f9b\u7684\u6765\u6e90\u5b9a\u4e49\u4e86\u5177\u4f53 k,\u4ee5\u6765\u6e90\u4e3a\u51c6**\u3002\n\n### 2.4 \u8bad\u7ec3/\u8bc4\u4f30\u534f\u8bae\n- \u7528\u524d 4 \u6761\u8f68\u8ff9\u7684\u538b\u7f29\u7248\u8bad\u7ec3 MDGEN \u7c7b\u6a21\u578b(\u6ed1\u52a8\u7a97\u53e3:\u8f93\u5165\u8fde\u7eed m=8 \u4e2a\u7c97\u5e27,\u76ee\u6807\u4e3a\u5e27\u95f4\u5168\u90e8 k\u22121 \u4e2a\u4e2d\u95f4\u5e27);\n- \u7b2c 5 \u6761\u8f68\u8ff9\u6574\u6761\u7559\u51fa\u7528\u4e8e\u8bc4\u4f30(\u8f68\u8ff9\u7ea7\u5212\u5206,\u907f\u514d\u5e27\u6cc4\u6f0f);\n- \u6bcf\u4e2a\u65b9\u6cd5 \u00d7 \u6bcf\u4e2a k \u6761\u4ef6\u4e0b,\u5bf9\u7559\u51fa\u8f68\u8ff9\u7684\u6bcf\u4e2a\u7c97\u5e27\u95f4\u9694\u751f\u6210 k\u22121 \u4e2a\u4e2d\u95f4\u5e27,\u4e0e\u91d1\u6807\u51c6\u5bf9\u5e94\u5e27\u4e00\u4e00\u914d\u5bf9\u6bd4\u8f83\u3002\n\n---\n\n## 3. \u65b9\u6cd5\u4e0e\u5bf9\u7167(\u7cbe\u786e\u8bbe\u5b9a)\n\n| # | \u65b9\u6cd5 | \u8bbe\u5b9a |\n|---|------|------|\n| A | **\u91d1\u6807\u51c6\u4e0a\u754c** | \u9ad8\u9891\u6a21\u62df\u7684\u539f\u59cb\u5e27,\u4e0d\u751f\u6210 |\n| B | **MDGEN(\u5f85\u8bc4\u65b9\u6cd5)** | \u7ed9\u5b9a\u7684\u751f\u6210\u5f0f\u6a21\u578b,\u8f93\u5165 m=8 \u4e2a\u7c97\u5e27,\u9010\u6bb5\u751f\u6210 k\u22121 \u4e2a\u4e2d\u95f4\u5e27 |\n| C | **\u7ebf\u6027\u63d2\u503c** | \u5bf9\u7c97\u5e27\u7b1b\u5361\u5c14\u5750\u6807\u4e0e\u626d\u8f6c\u89d2\u505a\u7ebf\u6027\u63d2\u503c(\u626d\u8f6c\u89d2\u6309\u6700\u77ed\u89d2\u8def\u5f84\u63d2\u503c);\u5bf9\u7167\u7ec4,\u4e0d\u4f5c\u7269\u7406\u6295\u5f71 |\n| D | **\u51bb\u7ed3\u63a7\u5236** | \u4e2d\u95f4\u5e27 = \u590d\u5236\u6700\u8fd1\u7684\u7c97\u5e27(\u96f6\u52a8\u529b\u5b66\u9884\u6d4b),\u68c0\u9a8c\u6307\u6807\u5bf9\"\u5b8c\u5168\u4e0d\u52a8\"\u7684\u654f\u611f\u5ea6 |\n| E | **\u968f\u673a\u57fa\u7ebf** | (i) \u5bf9\u51bb\u7ed3\u5e27\u5750\u6807\u52a0\u9ad8\u65af\u6270\u52a8(\u03c3 = \u91d1\u6807\u51c6\u76f8\u90bb\u5e27\u5750\u6807 RMSD);(ii) \u4ece\u91d1\u6807\u51c6\u5e73\u8861\u6001\u5206\u5e03\u4e2d\u968f\u673a\u62bd\u5e27(\u4e22\u65f6\u5e8f\u4fe1\u606f)\u3002\u4e24\u8005\u5206\u5f00\u62a5\u544a |\n| F | **\u957f\u65f6\u6b65\u76f4\u63a5\u6a21\u62df** | \u4ee5 \u0394t = k\u00b7\u0394t\u2080 \u7684\u7c97\u6b65\u957f\u76f4\u63a5\u79ef\u5206\u540c\u4e00\u6761\u8f68\u8ff9(\u540c\u521d\u59cb\u6761\u4ef6\u3001\u540c\u968f\u673a\u79cd\u5b50\u6570),\u68c0\u9a8c\"\u76f4\u63a5\u7528\u5927\u6b65\u957f\u6a21\u62df\"\u662f\u5426\u53ef\u884c\u53ca\u6570\u503c\u7a33\u5b9a\u6027 |\n\n\u6240\u6709\u751f\u6210\u65b9\u6cd5\u5bf9\u6bcf\u4e2a\u6761\u4ef6\u4f7f\u7528 \u22653 \u4e2a\u968f\u673a\u79cd\u5b50,\u6c47\u603b\u540e\u62a5\u544a\u5747\u503c\u4e0e\u79bb\u6563\u5ea6\u3002\n\n---\n\n## 4. \u6307\u6807\u5b9a\u4e49(\u542b\u8ba1\u7b97\u5f0f)\n\n\u8bbe\u5bf9\u67d0\u7c97\u5e27\u95f4\u9694 t \u2192 t+k\u0394t\u2080,\u751f\u6210\u5e27\u4e3a {x\u0302_{t+i\u0394t\u2080}},\u91d1\u6807\u51c6\u5e27\u4e3a {x_{t+i\u0394t\u2080}},i=1\u2026k\u22121\u3002\u626d\u8f6c\u89d2\u9010\u5e27\u8bb0 \u03c6_j(t),j \u904d\u5386\u6240\u6709\u4e8c\u9762\u89d2(\u5706\u5ea6\u91cf,\u5355\u4f4d\u5f27\u5ea6)\u3002\n\n### 4.1 \u9010\u5e27\u77ac\u65f6\u4fdd\u771f(\u4e3b\u6307\u6807)\n1. **\u626d\u8f6c\u89d2\u9010\u5e27\u8bef\u5dee**:\n TFE(i) = (1/J) \u03a3_j d_circ(\u03c6\u0302_j(i), \u03c6_j(i)),\u5176\u4e2d d_circ(a,b) = |wrap_\u03c0(a\u2212b)|\u3002\n \u62a5\u544a TFE \u7684\u6574\u4f53\u5747\u503c\u3001\u5206\u5e03\u53ca\u968f i=1\u2026k\u22121 \u7684**\u8bef\u5dee\u8f6e\u5ed3**(\u8bef\u5dee\u662f\u5426\u968f\u79bb\u951a\u70b9\u8ddd\u79bb\u589e\u5927\u800c\u7d2f\u79ef,\u53ef\u533a\u5206\"\u771f\u6b63\u5efa\u6a21\u52a8\u529b\u5b66\"\u4e0e\"\u63d2\u503c\")\u3002\n2. **\u7b1b\u5361\u5c14\u5e27 RMSD**(\u53c2\u8003\u6784\u8c61\u5bf9\u9f50\u540e):RMSD(i) = \u221a( (1/N_atoms) \u03a3 \u2016r\u0302(i) \u2212 r(i)\u2016\u00b2 )\u3002\n\n### 4.2 \u52a8\u529b\u5b66\u4fdd\u771f(\u6838\u5fc3\u533a\u5206\u6307\u6807)\n3. **\u626d\u8f6c\u89d2 ACF**:\n C_j(\u03c4) = \u27e8d_circ(\u03c6_j(t), \u03c6_j(t+\u03c4))\u27e9_t \u5bf9\u5f52\u4e00\u5316(\u6216\u5bf9 cos/sin \u5206\u91cf\u8ba1\u7b97\u6807\u51c6 ACF)\u3002\n \u6bd4\u8f83:(a) **\u8870\u51cf\u65f6\u95f4** \u03c4_dec(C \u8870\u51cf\u5230 1/e \u7684\u5ef6\u8fdf);(b) **\u632f\u8361\u5468\u671f**(\u5bf9 ACF \u6216\u5176\u8c31\u505a\u5cf0\u68c0\u6d4b/FFT \u4e3b\u9891)\u3002\u8bef\u5dee\u62a5\u544a\u4e3a |\u03c4\u0302_dec \u2212 \u03c4_dec^gold| / \u03c4_dec^gold \u4e0e\u9891\u7387\u76f8\u5bf9\u8bef\u5dee\u3002\n4. **\u89d2\u901f\u5ea6/\u52a0\u901f\u5ea6\u7edf\u8ba1**:\u4e2d\u95f4\u5e27\u7684 \u0394\u03c6 \u9010\u5e27\u5206\u5e03\u4e0e\u91d1\u6807\u51c6\u7684\u5206\u5e03\u6bd4\u8f83(KS \u68c0\u9a8c\u7edf\u8ba1\u91cf),\u533a\u5206\"\u5e45\u503c\u6b63\u786e\u4f46\u8282\u5f8b\u9519\u8bef\"\u7684\u60c5\u5f62\u3002\n\n### 4.3 \u9759\u6001\u7ed3\u6784\u4fdd\u771f\n5. **RDF**:\u5bf9\u91cd\u539f\u5b50\u5bf9/\u6c34\u6c27(\u5982\u663e\u5f0f\u6eb6\u5242)\u8ba1\u7b97 g(r),\u62a5\u544a\u4e0e\u91d1\u6807\u51c6 RDF \u7684 L2 \u504f\u5dee\u3002\n6. **\u952e\u957f/\u952e\u89d2\u5206\u5e03**:\u76f4\u65b9\u56fe KL \u6563\u5ea6\u6216 Jensen\u2013Shannon \u6563\u5ea6;\u5e76\u7edf\u8ba1**\u7269\u7406\u5408\u6cd5\u6027\u8fdd\u89c4\u7387**(\u952e\u957f\u8d8a\u754c >3\u03c3\u3001\u4e0d\u5408\u7406\u89d2)\u3002\n\n### 4.4 \u654f\u611f\u6027\u4e0e\u6c47\u603b\n7. \u6bcf\u4e2a\u6307\u6807\u5728 k \u2208 {10, 50, 100} \u00d7 N \u6761\u8f68\u8ff9\u4e0a\u6c47\u603b;\u4e3b\u7ed3\u8bba\u4f9d\u636e **TFE \u5747\u503c\u4e0e \u03c4_dec \u76f8\u5bf9\u8bef\u5dee** \u4e24\u9879\u3002\n\n---\n\n## 5. \u7edf\u8ba1\u68c0\u9a8c\u8ba1\u5212\n\n- **\u91cd\u590d\u5355\u5143**:\u72ec\u7acb\u8f68\u8ff9(\u6bcf\u6761\u4ef6 5 \u6761)\u00d7 \u751f\u6210\u79cd\u5b50(\u22653);\u914d\u5bf9\u6bd4\u8f83\u6309\"\u540c\u4e00\u7c97\u5e27\u95f4\u9694\u3001\u540c\u4e00\u91d1\u6807\u51c6\u5e27\"\u914d\u5bf9\u3002\n- **\u4e3b\u68c0\u9a8c**:\u5bf9\u6bcf\u4e2a (\u65b9\u6cd5, k),TFE \u4e0e \u03c4_dec \u8bef\u5dee\u5206\u5e03\u505a **Wilcoxon \u7b26\u53f7\u79e9\u68c0\u9a8c**(MDGEN vs \u6bcf\u4e2a\u5bf9\u7167,\u914d\u5bf9)\u6216 **bootstrap(10\u2074 \u91cd\u91c7\u6837)95% CI** \u4e4b\u5dee\u3002\n- **\u591a\u91cd\u6bd4\u8f83**:Benjamini\u2013Hochberg(FDR q=0.05)\u8de8\u65b9\u6cd5\u00d7\u6307\u6807\u6821\u6b63;\u540c\u65f6\u62a5\u544a\u6548\u5e94\u91cf(Cohen's d \u6216\u914d\u5bf9 rank-biserial)\u3002\n- **\u5224\u8bfb\u6807\u51c6(\u4e8b\u5148\u5b9a\u4e49)**:\n - **\"\u51c6\u786e\u6062\u590d\"\u6210\u7acb** \u5f53\u4e14\u4ec5\u5f53:MDGEN \u7684 TFE \u663e\u8457\u4f4e\u4e8e\u7ebf\u6027\u63d2\u503c\u3001\u51bb\u7ed3\u3001\u968f\u673a\u57fa\u7ebf(FDR \u6821\u6b63\u540e),\u4e14\u5176 \u03c4_dec \u4e0e\u632f\u8361\u5468\u671f\u76f8\u5bf9\u8bef\u5dee \u2264 \u9884\u6ce8\u518c\u9608\u503c(\u5efa\u8bae 20%,\u5373\u5047\u8bbe,\u9700\u7814\u7a76\u8005\u786e\u8ba4),\u4e14 RDF/\u952e\u957f\u952e\u89d2\u504f\u5dee\u4e0e\u91d1\u6807\u51c6\u7684\u62bd\u6837\u566a\u58f0\u540c\u91cf\u7ea7\u3002\n - \u82e5 MDGEN \u4ec5\u5728\u9759\u6001\u6307\u6807(4.3)\u8fbe\u6807\u800c\u52a8\u529b\u5b66\u6307\u6807(4.2)\u4e0d\u8fbe\u6807 \u2192 \u7ed3\u8bba\u4e3a\"\u7ed3\u6784\u6b63\u786e\u4f46\u5feb\u901f\u52a8\u529b\u5b66\u672a\u6062\u590d\";\u82e5\u8bef\u5dee\u8f6e\u5ed3(4.1-1)\u968f i \u5355\u8c03\u7d2f\u79ef\u81f3\u4e0e\u51bb\u7ed3\u63a7\u5236\u65e0\u5dee\u5f02 \u2192 \u5224\u5b9a\"\u4ec5\u590d\u5236\u7aef\u70b9\u4fe1\u606f\"\u3002\n- **\u5bf9 k \u7684\u654f\u611f\u6027**:\u4ee5 k \u4e3a\u56e0\u53d8\u91cf\u753b\u5404\u65b9\u6cd5 TFE/\u03c4_dec \u8bef\u5dee\u66f2\u7ebf;\u68c0\u9a8c\u65b9\u6cd5\u00d7k \u4ea4\u4e92(\u5982 Friedman \u68c0\u9a8c)\u3002\n\n---\n\n## 6. \u8ba1\u7b97\u53ef\u884c\u6027\u4f30\u7b97(\u8bbe\u8ba1\u8bba\u8bc1,\u4e0d\u6267\u884c)\n\n- \u4e19\u6c28\u9178\u4e8c\u80bd(\u7ea6 2000\u20132500 \u539f\u5b50,\u542b\u663e\u5f0f\u6c34):OpenMM CPU \u5728\u591a\u6838\u4e0a\u5178\u578b\u901f\u5ea6 ~ \u6570\u5341\u81f3\u6570\u767e ns/\u5929;5 \u00d7 100 ns \u2248 500 ns,\u5728 224 \u6838\u673a\u5668\u4e0a**\u6570\u5929\u5185\u53ef\u884c**(\u6570\u91cf\u7ea7\u4f30\u7b97,\u975e\u627f\u8bfa)\u3002\n- \u65b9\u6cd5 F(\u7c97\u6b65\u957f\u76f4\u63a5\u6a21\u62df)\u989d\u5916 3 \u4e2a k \u00d7 5 \u6761 \u00d7 100 ns \u7b49\u6548\u65f6\u957f\u7684\u77ed\u8f68\u8ff9,\u603b\u91cf\u540c\u91cf\u7ea7\u3002\n- MDGEN \u8bad\u7ec3:\u6570\u636e\u91cf\u4e3a ~4\u00d710\u2075 \u9ad8\u9891\u5e27(\u8f93\u5165\u4fa7\u7c97\u5e27 2\u00d710\u2074 \u6bb5),\u5c0f\u6a21\u578b(CPU \u53ef\u8bad);\u63a8\u7406\u4e3a\u9010\u6bb5\u751f\u6210,\u5f00\u9500\u53ef\u5ffd\u7565\u76f8\u5bf9\u6a21\u62df\u3002\n- **\u7ed3\u8bba**:\u5728 CPU-only\u3001\u65e0 GPU \u7ea6\u675f\u4e0b,\u4e3b\u4f53\u7cfb\u53ef\u884c;\u6b21\u4f53\u7cfb(Chignolin)\u663e\u5f0f\u6eb6\u5242\u8f68\u8ff9\u6210\u672c\u589e\u7ea6\u4e00\u4e2a\u6570\u91cf\u7ea7,\u5217\u4e3a\u53ef\u9009/\u964d\u7ea7\u9879\u3002**\u8be5\u4f30\u7b97\u662f\u6570\u91cf\u7ea7\u63a8\u65ad(\u5047\u8bbe)**,\u6267\u884c\u524d\u9700\u5b9e\u6d4b\u57fa\u51c6\u901f\u5ea6\u786e\u8ba4\u3002\n\n---\n\n## 7. \u8d44\u6599\u786e\u8ba4 vs \u5047\u8bbe\u6e05\u5355\n\n**\u8d44\u6599\u5df2\u786e\u8ba4(\u4ec5\u4e24\u9879)**\n1. \u7814\u7a76\u95ee\u9898:MDGEN \u662f\u5426\u51c6\u786e\u6062\u590d\u5b50\u91c7\u6837\u8f68\u8ff9\u4e2d\u7f3a\u5931\u7684\u5feb\u901f\u65f6\u95f4\u6b65\u52a8\u529b\u5b66(\u5982\u626d\u8f6c\u89d2\u632f\u8361)\u3002\n2. \u4efb\u52a1\u6027\u8d28:\u7eaf\u8bbe\u8ba1\u3001\u4e0d\u8981\u6c42\u6267\u884c;\u4ed3\u5e93\u65e0\u5176\u4ed6\u8d44\u6599\u3002\n\n**\u8bbe\u8ba1\u524d\u63d0\u5047\u8bbe(\u7ecf\u7814\u7a76\u8005\u672c\u8f6e\u6f84\u6e05\u91c7\u7eb3,\u4ecd\u5c5e\u80cc\u666f\u77e5\u8bc6\u5c42\u8bbe\u5b9a,\u975e\u8d44\u6599\u4e8b\u5b9e)**\n3. MDGEN \u5b9a\u4e49:\u751f\u6210\u5f0f\u6a21\u578b,\u7531\u538b\u7f29\u65f6\u95f4\u6b65\u7c97\u5e27\u751f\u6210\u4e2d\u95f4\u5e27;\u4e0d\u590d\u73b0\u539f\u67b6\u6784,\u89c6\u4e3a\u7ed9\u5b9a\u9ed1\u7bb1\u3002\n4. MDCT \u5b9a\u4e49:\u4ee5\u5927\u4e8e\u79ef\u5206\u6b65\u957f\u7684\u95f4\u9694\u4fdd\u5b58\u7684\u8f68\u8ff9\u3002\n5. \"\u5feb\u632f\u8361\"\u7684\u64cd\u4f5c\u5316:\u9010\u5e27\u77ac\u65f6\u626d\u8f6c\u89d2\u8bef\u5dee + A